:root{color-scheme:light;font-family:Arial,Helvetica,sans-serif;color:#202020;background:#f5f5f5;font-size:15px;line-height:1.5}
*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0}header{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;padding:28px 32px;background:#fff;border-bottom:1px solid #bbb}h1{font-size:30px;letter-spacing:-.025em;margin:4px 0 6px}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px;margin:0 0 8px}p{margin:6px 0 14px}nav{display:flex;flex-wrap:wrap;gap:18px;padding-top:14px}a{color:inherit;text-underline-offset:3px}.eyebrow{font:11px/1.6 ui-monospace,monospace;letter-spacing:.08em}.small,small{font-size:12px;color:#535353}.hash,pre{overflow-wrap:anywhere}pre{white-space:pre-wrap;font:12px/1.5 ui-monospace,monospace;margin:8px 0}#message{margin:0;padding:12px 32px;border-bottom:1px solid #bbb;background:#eaeaea;min-height:46px;overflow-wrap:anywhere}main{display:grid;grid-template-columns:290px minmax(0,1fr);max-width:1700px;margin:auto;min-height:70vh}aside{padding:24px;border-right:1px solid #bbb;background:#fafafa;min-width:0}.workspace{padding:26px 30px;min-width:0}#empty{max-width:680px;margin:60px auto}.section-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin:22px 0 12px}.section-head:first-child{margin-top:0}.section-head h2{margin:0}button,input,select,textarea{font:inherit;border-radius:2px}button,.file-button{border:1px solid #a1a1a1;background:#fff;color:#202020;padding:8px 12px;cursor:pointer;line-height:1.4}button:hover,.file-button:hover{background:#e9e9e9}button:disabled{cursor:default;color:#767676;background:#f2f2f2;border-color:#d2d2d2}button.primary{background:#292929;color:#fff;border-color:#292929}button.primary:hover{background:#474747}button.primary:disabled{background:#dedede;color:#6c6c6c;border-color:#bfbfbf}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,.file-button:focus-within{outline:2px solid #111;outline-offset:3px}.file-button{display:block;text-align:center;margin:12px 0}.file-button input{max-width:100%;display:block;font-size:12px;margin-top:8px}#refresh{width:100%;margin-bottom:16px}.return{display:block;width:100%;text-align:left;margin:0 0 9px;padding:12px;overflow-wrap:anywhere}.return[aria-current=true]{border:2px solid #333;padding:11px;background:#e9e9e9}.return strong,.return small{display:block}.actions{display:flex;flex-wrap:wrap;gap:8px}.metrics{display:flex;flex-wrap:wrap;gap:8px}.metrics span{border:1px solid #aaa;background:#fff;padding:7px 11px;font-size:13px}.pager{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:14px 0}.pager span{font-size:12px;color:#555}.pager button{padding:6px 9px;font-size:12px}details{margin:14px 0;border:1px solid #ccc;background:#fff;padding:10px 12px}summary{cursor:pointer;font-size:13px}label{display:block;font-size:13px;margin:8px 0 5px}input,select,textarea{border:1px solid #a9a9a9;background:#fff;color:#222;padding:8px;width:100%;min-width:0}input{min-height:40px}.section-head select{width:auto;margin-left:6px}textarea{resize:vertical}.table{overflow-x:auto;border:1px solid #bcbcbc;background:#fff}table{border-collapse:collapse;width:100%;table-layout:fixed}th,td{text-align:left;vertical-align:top;padding:10px 12px;border-bottom:1px solid #d2d2d2;overflow-wrap:anywhere}th{background:#e8e8e8;font-size:12px}td{font-size:13px}td:first-child{width:32%}td button{text-align:left;width:100%;word-break:break-word;font:12px ui-monospace,monospace;padding:7px}tr[aria-selected=true]{background:#ededed}.histories{display:grid;grid-template-columns:1fr 1fr;gap:16px}.histories>section{border:1px solid #bbb;background:#fff;padding:16px;min-width:0}.history-row{border-bottom:1px solid #ccc;padding:8px 0}.history-row:last-child{border-bottom:0}.history-row strong{font-size:13px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}#choice-form{margin-top:18px;border:1px solid #aaa;background:#fff;padding:20px}#target-title{overflow-wrap:anywhere}footer{border-top:1px solid #bbb;padding:18px 32px;font:12px ui-monospace,monospace;color:#555}
@media(max-width:1000px){main{grid-template-columns:240px minmax(0,1fr)}aside{padding:18px}.workspace{padding:20px}.histories{grid-template-columns:1fr}}
@media(max-width:720px){header{padding:20px;display:block}nav{padding-top:0;font-size:13px}#message{padding:12px 20px}main{display:block}aside{border-right:0;border-bottom:1px solid #aaa}.workspace{padding:20px}.histories,.form-grid{grid-template-columns:1fr}.actions button{flex:1;min-width:150px}table,tbody,tr,td{display:block}thead{display:none}tr{border-bottom:2px solid #aaa}td{border:0;padding:7px 10px}td:before{content:attr(data-label);font-weight:bold;display:block;font-size:11px;margin-bottom:3px}td:first-child{width:100%}.section-head label{width:100%}.section-head select{max-width:100%;margin-left:0;width:100%}#empty{margin:20px auto}footer{padding:18px 20px}}

.continuation{margin:18px 0;padding:16px;border:1px solid #aaa;background:#fff}.continuation .actions{align-items:center}.continuation .actions>a{padding:8px 12px;border:1px solid #999;background:#fff;border-radius:2px;text-decoration:none}.continuation .actions>a:hover{background:#e9e9e9}#all-comparisons{width:100%;margin-bottom:10px}#list-context{overflow-wrap:anywhere}

// MIT — The original private listener; provider/reviewer content is rendered as text.
const $=id=>document.getElementById(id),session='sf-resource-session';
const stored=(key,fallback='')=>{try{return sessionStorage.getItem(key)??fallback;}catch{return fallback;}};
const store=(key,value)=>{try{if(value===null)sessionStorage.removeItem(key);else sessionStorage.setItem(key,value);}catch{}};
let token=location.hash.slice(1)||stored(session);
if(location.hash){store(session,token);history.replaceState(null,'',location.pathname+location.search);}
let selected=null,target=null,planEpoch=0,listPage=0,targetPage=0,targetTotal=0,choicePending=null,editorPlan=null,choiceRevision=0;
const historyPage={local:0,incoming:0};
const initialQuery=new URLSearchParams(location.search);
const validId=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
const reviewRoute=(path,values)=>{const query=new URLSearchParams(Object.entries(values).filter(([,value])=>validId(value)));return path+(query.size?'?'+query:'');};
let comparisonFilter=validId(initialQuery.get('comparison'))?initialQuery.get('comparison'):null;
function listContext(){
  $('list-context').textContent=comparisonFilter?'Saved incoming reviews for comparison '+comparisonFilter:'Saved incoming reviews for every comparison';
  $('all-comparisons').hidden=!comparisonFilter;
  if(!selected)$('edition-review').href=reviewRoute('/comparisons',{id:comparisonFilter});
}
function bindComparison(){
  const applied=selected.state==='APPLIED',url=reviewRoute('/comparisons',{id:selected.comparisonId,incoming:selected.id});
  $('edition-review').href=$('open-comparison').href=url;
  $('open-comparison').textContent=applied?'Continue in the accepted comparison':'Open the local comparison';
  $('open-returned-journals').href=reviewRoute('/review-returns',{comparison:selected.comparisonId});
  $('download-accepted').hidden=!applied;
  $('continuation-state').textContent=applied?
    'The accepted decisions are saved in this comparison. Continue editing it or export its complete reviewer history.':
    'Resolution choices stay in this return until applied. The comparison opens its currently saved local decisions.';
}
const message=value=>{$('message').textContent=value;};
const node=(tag,text)=>{const result=document.createElement(tag);if(text!==undefined)result.textContent=text;return result;};
const operation=()=>crypto.randomUUID();
const run=fn=>Promise.resolve().then(fn).catch(error=>message(error.message));
const draftKey=()=>selected&&target?'sf-return-choice:'+selected.id+':'+target.target:null;
function remember(){if(!draftKey())return;store(draftKey(),JSON.stringify({choice:$('choice').value,actor:$('actor').value,note:$('note').value,status:$('status').value,planSha256:editorPlan,expectedRevision:choiceRevision,pending:choicePending}));}
async function api(path,method='GET',input,root='/api/comparisons/returns'){
  const response=await fetch(root+path,{method,headers:{Authorization:'Bearer '+token,...(input===undefined?{}:{'Content-Type':'application/json'})},body:input===undefined?undefined:JSON.stringify(input)});
  const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error??'HTTP_'+response.status),{status:response.status});return data;
}
function decisionView(decision){
  const section=node('section');section.className='history-row';
  if(!decision){section.append(node('p','No saved decision.'));return section;}
  section.append(node('strong',decision.status+' · '+decision.actor+' · r'+decision.revision),node('p',decision.recordedAt),node('pre',decision.note));
  if(decision.reviewReturn){const details=node('details');details.append(node('summary','Returned-review resolution'),node('pre',JSON.stringify(decision.reviewReturn,null,2)));section.append(details);}
  return section;
}
async function list(){
  listContext();const data=await api('?'+new URLSearchParams({offset:String(listPage*20),limit:'20',...(comparisonFilter?{comparison:comparisonFilter}:{})}));
  $('returns').replaceChildren();for(const entry of data.items){const button=node('button');button.type='button';button.className='return';button.setAttribute('aria-current',String(selected?.id===entry.id));
    button.append(node('strong',entry.state+' · '+entry.id.slice(0,12)),node('small',entry.receivedAt),node('small','Comparison '+entry.comparisonId.slice(0,16)));
    button.onclick=()=>run(()=>select(entry.id));$('returns').append(button);}
  $('list-prev').disabled=listPage===0;$('list-next').disabled=(listPage+1)*20>=data.total;
  $('list-page').textContent=data.total?`${listPage*20+1}–${Math.min((listPage+1)*20,data.total)} / ${data.total}`:'No saved returns';
}
function render(){
  bindComparison();
  $('empty').hidden=true;$('selected').hidden=false;$('return-id').textContent=selected.id;$('title').textContent='Returned review · '+selected.state;
  $('metrics').replaceChildren();const c=selected.counts;
  for(const label of [`${c.incomingAdvances} incoming additions`,`${c.conflicts} divergent targets`,`${c.unresolved} choices remaining`,`${c.localAdvances} newer local targets`,`${c.alreadyResolved} already resolved`])$('metrics').append(node('span',label));
  $('identities').textContent=JSON.stringify({comparisonId:selected.comparisonId,handoverSha256:selected.handoverSha256,resultSha256:selected.resultSha256,planSha256:selected.planSha256,receivedAt:selected.receivedAt},null,2);
  $('application').textContent=selected.application?`Applied ${selected.application.appliedAt}: ${selected.application.appendedDecisions} appended decisions, ${selected.application.resolvedTargets} resolved divergences.`:'Incoming revisions and choices are retained. Apply checks this complete plan before changing canonical review history.';
  if(selected.state==='APPLIED')store('sf-return-apply:'+selected.id,null);
  $('apply').disabled=selected.state!=='PENDING'||c.unresolved>0;
  $('apply').textContent=stored('sf-return-apply:'+selected.id)?'Retry pending apply':'Apply reviewed return';
}
async function loadTargets(){
  const id=selected.id,epoch=planEpoch;
  const data=await api('/'+id+'/targets?'+new URLSearchParams({offset:String(targetPage*25),limit:'25',state:$('filter').value}));
  if(epoch!==planEpoch||selected?.id!==id)return;
  if(data.planSha256!==selected.planSha256){message('Review changed in another session. Refresh the saved return before choosing.');$('apply').disabled=true;return;}
  targetTotal=data.total;$('targets').replaceChildren();for(const entry of data.items){const tr=node('tr');tr.setAttribute('aria-selected',String(target?.target===entry.target));
    const cell=node('td');cell.dataset.label='Target';const button=node('button',entry.path||'(root)');button.type='button';button.onclick=()=>run(()=>edit(entry));cell.append(button);tr.append(cell);
    for(const[label,value]of [['Relationship',entry.state.replaceAll('_',' ')],['Local / incoming revisions',`${entry.localRevision} / ${entry.incomingRevision} · shared ${entry.commonRevision}`],['Choice',entry.choice?(entry.choiceCurrent?'Saved: ':'Stale: ')+entry.choice.choice.replaceAll('_',' '):'—']]){const td=node('td',value);td.dataset.label=label;tr.append(td);}
    $('targets').append(tr);}
  $('target-prev').disabled=targetPage===0;$('target-next').disabled=(targetPage+1)*25>=targetTotal;
  $('target-page').textContent=targetTotal?`${targetPage*25+1}–${Math.min((targetPage+1)*25,targetTotal)} / ${targetTotal}`:'No targets in this view';
}
async function loadHistory(side){
  const id=selected.id,selectedTarget=target.target,epoch=planEpoch,offset=historyPage[side]*20;
  const data=await api('/'+id+'/history?'+new URLSearchParams({side,target:selectedTarget,offset:String(offset),limit:'20'}));
  if(epoch!==planEpoch||selected?.id!==id||target?.target!==selectedTarget)return;
  $(side+'-history').replaceChildren(...data.items.map(decisionView));
  $(side+'-prev').disabled=historyPage[side]===0;$(side+'-next').disabled=offset+20>=data.total;
  $(side+'-page').textContent=data.total?`${offset+1}–${Math.min(offset+20,data.total)} / ${data.total}`:'No revisions';
}
function lockChoice(){
  for(const id of ['choice','actor','status','note','load-current'])$(id).disabled=Boolean(choicePending);
  $('save-choice').textContent=choicePending?'Retry pending choice':'Save resolution choice';
  $('custom-status').hidden=$('choice').value!=='CUSTOM';
}
async function edit(entry,discard=false){
  remember();target=entry;$('review').hidden=false;$('target-title').textContent=entry.path||'(root)';
  $('common').textContent='Common history: '+entry.commonRevision+' revisions';
  $('local-latest').replaceChildren(decisionView(entry.localLatest));$('incoming-latest').replaceChildren(decisionView(entry.incomingLatest));
  $('target-explanation').textContent={CONFLICT:'Both reviewers changed this target after their common history. A saved resolution is required.',INCOMING_ADVANCES:'The incoming history extends the local history. Apply appends its new revisions unchanged.',LOCAL_ADVANCES:'The local history is newer. Incoming older revisions will not replace it.',UNCHANGED:'Both histories are identical.',ALREADY_RESOLVED:'A recorded local revision already resolves this exact incoming handover.'}[entry.state];
  $('choice-form').hidden=entry.state!=='CONFLICT'||selected.state!=='PENDING';
  if(discard)store(draftKey(),null);let draft;try{draft=JSON.parse(stored(draftKey(),'null'));}catch{}
  const value=draft??entry.choice??{choice:'KEEP_LOCAL',actor:stored('sf-comparison-reviewer'),note:'',status:'FOLLOW_UP'};
  $('choice').value=value.choice;$('actor').value=value.actor;$('note').value=value.note;$('status').value=value.status??'FOLLOW_UP';
  editorPlan=draft?.planSha256??selected.planSha256;choiceRevision=draft?.expectedRevision??entry.choice?.revision??0;choicePending=draft?.pending??null;
  $('choice-state').textContent=editorPlan!==selected.planSha256?'This retained draft uses an older plan. Load the current saved choice before saving.':`Choice revision ${choiceRevision}. ${entry.choiceCurrent?'A current choice is saved.':'No current choice is saved.'}`;
  lockChoice();for(const side of ['local','incoming'])historyPage[side]=Math.max(0,Math.ceil((side==='local'?entry.localRevision:entry.incomingRevision)/20)-1);
  await Promise.all([loadHistory('local'),loadHistory('incoming')]);
}
async function select(id){
  remember();const epoch=++planEpoch;target=null;choicePending=null;editorPlan=null;targetPage=0;$('review').hidden=true;
  const plan=await api('/'+id);if(epoch!==planEpoch)return;selected=plan;
  if(comparisonFilter!==plan.comparisonId){comparisonFilter=plan.comparisonId;listPage=0;}
  history.replaceState(null,'',reviewRoute('/comparison-returns',{id,comparison:comparisonFilter}));render();await Promise.all([loadTargets(),list()]);
  if(epoch===planEpoch)message(plan.state==='APPLIED'?'Returned review applied. Its original history remains available.':'Return loaded. Review the relationships and resolve any divergences.');
}
$('incoming-file').onchange=()=>run(async()=>{
  const file=$('incoming-file').files[0];if(!file)return;if(file.size>120*1024*1024)throw new Error('HANDOVER_FILE_TOO_LARGE');
  const packet=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()));
  const result=await api('','POST',{packet,operationId:operation()});$('incoming-file').value='';await select(result.id);
});
$('all-comparisons').onclick=()=>run(async()=>{comparisonFilter=null;listPage=0;history.replaceState(null,'',reviewRoute('/comparison-returns',{id:selected?.id}));await list();});
$('refresh').onclick=()=>run(()=>selected?select(selected.id):list());
$('list-prev').onclick=()=>{listPage--;run(list);};$('list-next').onclick=()=>{listPage++;run(list);};
$('target-prev').onclick=()=>{targetPage--;run(loadTargets);};$('target-next').onclick=()=>{targetPage++;run(loadTargets);};
$('filter').onchange=()=>{targetPage=0;run(loadTargets);};
for(const side of ['local','incoming']){ $(side+'-prev').onclick=()=>{historyPage[side]--;run(()=>loadHistory(side));};$(side+'-next').onclick=()=>{historyPage[side]++;run(()=>loadHistory(side));}; }
for(const id of ['actor','note','status','choice'])$(id).addEventListener('input',()=>{lockChoice();remember();});
$('load-current').onclick=()=>run(()=>edit(target,true));
$('choice-form').onsubmit=event=>{event.preventDefault();run(async()=>{
  if(!selected||!target)return;const id=selected.id,selectedTarget=target.target,epoch=planEpoch;
  if(!choicePending)choicePending={target:selectedTarget,planSha256:editorPlan,expectedRevision:choiceRevision,operationId:operation(),choice:$('choice').value,actor:$('actor').value,note:$('note').value,
    ...($('choice').value==='CUSTOM'?{status:$('status').value}:{})};
  const input=choicePending,key=draftKey();remember();lockChoice();
  try{await api('/'+id+'/choose','POST',input);store(key,null);store('sf-comparison-reviewer',input.actor);
    if(epoch!==planEpoch||target?.target!==selectedTarget)return;choicePending=null;target=null;await select(id);message('Resolution choice saved. Apply commits the reviewed return.');
  }catch(error){if(error.status>=400&&error.status<500&&epoch===planEpoch&&target?.target===selectedTarget){choicePending=null;remember();lockChoice();}throw error;}
});};
$('apply').onclick=()=>run(async()=>{
  const id=selected.id,key='sf-return-apply:'+id;let input;try{input=JSON.parse(stored(key,'null'));}catch{}
  if(!input)input={planSha256:selected.planSha256,operationId:operation()};store(key,JSON.stringify(input));$('apply').disabled=true;
  try{const result=await api('/'+id+'/apply','POST',input);store(key,null);await select(id);message(`Applied return: ${result.appendedDecisions} appended decisions; ${result.resolvedTargets} resolved divergences.`);}
  catch(error){
    const after=await api('/'+id).catch(()=>null);
    if(after?.state==='APPLIED'&&after.application?.planSha256===input.planSha256){store(key,null);await select(id);message('Applied return recovered after the response was interrupted.');return;}
    if(error.status>=400&&error.status<500)store(key,null);await select(id);throw error;
  }
});
function downloadPrepared(prepared){
  if(!/^\/transfer\/[A-Za-z0-9_-]+$/.test(prepared.url))throw new Error('Invalid native download descriptor.');
  const link=node('a');link.href=prepared.url;link.download='';document.body.append(link);link.click();link.remove();
}
$('download').onclick=()=>run(async()=>{downloadPrepared(await api('/'+selected.id+'/download','POST',{format:'json'}));message('Complete original incoming review prepared.');});
$('download-accepted').onclick=()=>run(async()=>{
  const button=$('download-accepted'),id=selected.comparisonId;button.disabled=true;
  try{downloadPrepared(await api('/comparisons/'+id+'/download','POST',{format:'json'},'/api/review-returns'));message('Accepted comparison and complete reviewer histories prepared.');}finally{button.disabled=false;}
});
run(async()=>{
  const id=initialQuery.get('id');
  if(initialQuery.has('id')&&!validId(id))throw new Error('The return link is incomplete. Open a saved incoming review.');
  if(initialQuery.has('comparison')&&!comparisonFilter)throw new Error('The comparison link is incomplete. Open a saved comparison.');
  await list();if(id)await select(id);else message('Open a returned handover or select a saved return.');
});
window.addEventListener('pagehide',remember);

// MIT — Provider strings and review notes enter the DOM only as text.
const $=id=>document.getElementById(id),session='sf-resource-session';
let token=location.hash.slice(1)||sessionStorage.getItem(session)||'';
if(location.hash){sessionStorage.setItem(session,token);history.replaceState(null,'',location.pathname+location.search);}
let selected=null,target='*',targetPath='Whole case',revision=0,page=0,casePage=0,total=0,epoch=0,timer,pending=null,editorIdentity=null,savedDecision=null,editorGeneration=0,editorLoading=false;
const key=()=>selected?'sf-comparison-draft:'+selected.id+':'+target:null;
const initialQuery=new URLSearchParams(location.search);
const validId=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
const reviewRoute=(path,values)=>{const query=new URLSearchParams(Object.entries(values).filter(([,value])=>validId(value)));return path+(query.size?'?'+query:'');};
let contextComparison=initialQuery.get('id'),returnContext={incoming:initialQuery.get('incoming'),returned:initialQuery.get('returned')};
function bindReviewNavigation(comparison){
  if(contextComparison!==comparison.id){contextComparison=comparison.id;returnContext={};}
  const incoming=reviewRoute('/comparison-returns',{comparison:comparison.id,id:returnContext.incoming});
  const returned=reviewRoute('/review-returns',{comparison:comparison.id,id:returnContext.returned});
  for(const id of ['open-incoming-returns','receive-incoming-handover'])$(id).href=incoming;
  for(const id of ['open-returned-journals','receive-returned-journal'])$(id).href=returned;
  const url=reviewRoute('/comparisons',{id:comparison.id,...returnContext});
  if(location.pathname+location.search!==url)history.replaceState(null,'',url);
}
function draftState(){
  if(!selected||editorIdentity!==selected.id+':'+target)return;
  const value=draft(),changed=Boolean(pending)||['actor','status','note'].some(name=>value[name]!==savedDecision?.[name]);
  $('draft-state').textContent=pending?'A save is pending. Retry it to include this decision in the exported review.':changed?
    'Unsaved decision edits are retained in this browser. Save the decision to include them in the complete review.':
    savedDecision?.revision===0?'No decision is saved for this target.':'This decision matches the saved review.';
  return changed;
}
const message=text=>{$('message').textContent=text;};
const node=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
const operationId=()=>crypto.randomUUID?.()??Array.from(crypto.getRandomValues(new Uint8Array(24)),b=>b.toString(16).padStart(2,'0')).join('');
const run=task=>Promise.resolve().then(task).catch(e=>message(e.message));
async function api(path,method='GET',input){
  const response=await fetch('/api'+path,{method,headers:{Authorization:'Bearer '+token,...(input===undefined?{}:{'Content-Type':'application/json'})},body:input===undefined?undefined:JSON.stringify(input)});
  const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error??'HTTP_'+response.status),{status:response.status});return data;
}
async function resources(){
  const result=await api('/resources?'+new URLSearchParams({q:$('resource-query').value,limit:'200'}));$('resource-options').replaceChildren();
  for(const r of result.items){const option=node('option');option.value=r.id;option.label=r.name+' · '+r.intentId+' · '+r.bytes+' bytes';$('resource-options').append(option);}
  $('source-count').textContent=`${result.items.length} of ${result.total} matching files. Select an ID or paste one from the library.`;
}
async function cases(){
  const data=await api('/comparisons?'+new URLSearchParams({offset:String(casePage*20),limit:'20'}));
  $('cases').replaceChildren();for(const c of data.items){
    const button=node('button');button.className='case';button.type='button';button.setAttribute('aria-current',String(selected?.id===c.id));
    button.append(node('strong',c.input.before.name+' → '+c.input.after.name),node('small',c.state+' · '+(c.summary?.totalChanges??'—')+' changes · '+c.id.slice(0,12)));
    button.onclick=()=>run(()=>select(c.id));$('cases').append(button);
  }
  $('case-prev').disabled=casePage===0;$('case-next').disabled=(casePage+1)*20>=data.total;
