      const plan=plansById.get(receipt.planId),appended=receipt.actions.reduce((sum,action)=>sum+action.appended,0),conflicts=receipt.actions.filter(action=>action.classification==='CONFLICT').length;
      yield '<article class="lineage-receipt"><h4>'+esc(plan?.label??'Retained review plan')+'</h4><p><strong>'+esc(receipt.actor)+'</strong> · '+esc(receipt.recordedAt)+'</p><p>'+appended+' decision revisions appended · '+conflicts+' divergent targets reconciled · '+receipt.actions.length+' targets considered</p><details><summary>Complete reconciliation record</summary><pre>'+esc(JSON.stringify(receipt,null,2))+'</pre></details></article>';
    }
