    for(const source of lineage.sources){
      const targets=new Set(source.decisions.map(decision=>decision.target)).size;
      yield '<details class="lineage-source"><summary><strong>'+(source.id===currentId?'Current saved journal':'Retained reviewer journal')+'</strong> · '+source.decisions.length+' revisions across '+targets+' targets<small>'+esc(source.id)+'</small></summary>';
      for(const d of source.decisions)yield '<section class="history"><strong>'+esc(d.target==='*'?'Whole case':d.target)+' · '+esc(d.status)+' · '+esc(d.actor)+' · revision '+d.revision+'</strong><p>'+esc(d.recordedAt)+'</p><pre>'+esc(d.note)+'</pre></section>';
      if(!source.decisions.length)yield '<p>No recorded decisions in this source journal.</p>';
      yield '<details><summary>Complete source record and decision provenance</summary><pre>'+esc(JSON.stringify(source,null,2))+'</pre></details></details>';
    }
    yield '<details><summary><strong>Complete return plans</strong> · '+lineage.plans.length+' retained plans</summary>';
    for(const plan of lineage.plans)yield '<article><h4>'+esc(plan.label)+'</h4><p>'+esc(plan.createdAt)+'</p><pre>'+esc(JSON.stringify(plan,null,2))+'</pre></article>';
    if(!lineage.plans.length)yield '<p>No return plans are recorded in this history.</p>';
    yield '</details></section>';
    yield '<script>(()=>{const root=document.getElementById("review-lineage");if(!root)return;const records=()=>Array.from(root.querySelectorAll("details"));document.getElementById("lineage-expand").addEventListener("click",()=>records().forEach(record=>{record.open=true;}));document.getElementById("lineage-collapse").addEventListener("click",()=>records().forEach(record=>{record.open=false;}));let closedBeforePrint=null;window.addEventListener("beforeprint",()=>{if(closedBeforePrint===null)closedBeforePrint=records().filter(record=>!record.open);records().forEach(record=>{record.open=true;});});window.addEventListener("afterprint",()=>{if(closedBeforePrint!==null)closedBeforePrint.forEach(record=>{record.open=false;});closedBeforePrint=null;});})();</script>';
  }
  async function* chunks(){
    if(format==='json'){
      yield '{"schema":'+JSON.stringify(RETURN_SCHEMA)+',"lineage":'+JSON.stringify(lineage)+',"handover":';
      yield* original.chunks;yield ',"bundleSha256":'+JSON.stringify(bundleSha256)+'}\n';return;
    }
    if(format==='html'){
      for await(const chunk of original.chunks){const end='</main></body></html>';
        if(chunk.includes(end)){yield chunk.replace(end,'');yield* appendix();yield end+'\n';}else yield chunk;
      }return;
    }
    yield* original.chunks;
    for(const source of lineage.sources)for(const d of source.decisions)yield csvRow(['returned_review',comparison.id,d.target,'',source.id,JSON.stringify(d),'','','',d.status,d.actor,d.note,d.revision,d.recordedAt,comparison.resultSha256]);
    for(const plan of lineage.plans)yield csvRow(['return_plan',comparison.id,'*','',plan.id,JSON.stringify(plan),'','','','','','','',plan.createdAt,comparison.resultSha256]);
    for(const receipt of lineage.receipts)yield csvRow(['reconciliation',comparison.id,'*','',receipt.id,JSON.stringify(receipt),'','','','',receipt.actor,'','',receipt.recordedAt,comparison.resultSha256]);
  }
  return {filename:'review-return-'+comparison.id.slice(0,16)+'.'+format,mime:original.mime,bundleSha256,chunks:chunks()};
}

