  for(const field of $('targets').querySelectorAll('input,textarea,select'))field.disabled=immutable;
  $('reviewer').disabled=busy||Boolean(draft.pending)||selected?.status!=='READY';
  $('apply-button').disabled=busy||(!draft.pending&&selected?.status!=='READY');
  $('apply-button').textContent=draft.pending?'Retry the original apply':'Apply reviewed return';
