function field(labelText,control){const label=element('label',labelText);label.append(control);return label;}
function resolutionCell(row){
  const cell=element('td');cell.dataset.label='Resolution';const value=draft.resolutions[row.target]??{target:row.target,choice:'',reason:'',status:'FOLLOW_UP',note:''};
  const choice=element('select');choice.setAttribute('aria-label','Resolution for '+row.target);
  for(const [key,text]of [['',row.classification==='CONFLICT'?'Choose a resolution':'Use safe default: '+row.suggested],['KEEP_LOCAL','Keep local decision'],['TAKE_RETURNED','Take returned decision'],['CUSTOM','Write a reconciled decision']]){const option=element('option',text);option.value=key;if(key==='TAKE_RETURNED'&&!row.returned){option.disabled=true;option.textContent='No returned decision available';}choice.append(option);}choice.value=value.choice;
  const reason=element('textarea');reason.rows=2;reason.maxLength=32768;reason.value=value.reason;
  const status=element('select');for(const key of ['FOLLOW_UP','ACCEPT','REJECT']){const option=element('option',key);option.value=key;status.append(option);}status.value=value.status;
  const note=element('textarea');note.rows=3;note.maxLength=32768;note.value=value.note;
  const reasonField=field('Resolution reason',reason),statusField=field('New decision',status),noteField=field('New finding',note);
