function render(value){
  selected=value;showComparison(value.comparisonId,value.status,value.id);$('selection').hidden=false;$('empty').hidden=true;$('plan-id').textContent=value.id;$('plan-label').textContent=value.label;$('export-id').value=value.comparisonId;
  $('metrics').replaceChildren();for(const text of [value.status,...Object.entries(value.counts).map(([name,n])=>n+' '+name.toLowerCase().replaceAll('_',' '))])$('metrics').append(element('span',text));
  $('state-explanation').textContent=value.status==='STALE'?'The local review changed after this preview. Refresh against its current journal before applying.':value.status==='APPLIED'?'This return has been applied. Its receipt and both source journals remain available.':value.status==='IMPORTED'?'This plan belongs to an earlier received workspace. Refresh it to create a local preview.':'Safe returned advances are selected automatically. Every divergent target needs an explicit resolution.';
  $('identities').textContent=JSON.stringify({comparisonId:value.comparisonId,baseJournal:value.baseId,returnedJournal:value.sourceId,currentJournal:value.currentJournalId},null,2);
  $('targets').replaceChildren();for(const row of value.targets.items){
