  const data=await api('/review-returns/plans/'+id);if(requestEpoch!==epoch)return;
  draft=readLocal(draftKey(id))??{resolutions:{},actor:sessionStorage.getItem('sf-return-reviewer')??'',pending:null};
  if(comparisonFilter!==data.comparisonId){comparisonFilter=data.comparisonId;planPage=0;}
