async function openHistory(sourceId,target,label,page){
  const mark={sourceId,target,label,page},planId=selected?.id,requestEpoch=epoch;historySelection=mark;
  const data=await api('/review-returns/sources/'+sourceId+'?'+new URLSearchParams({target,offset:String(page*50),limit:'50'}));
  if(historySelection!==mark||epoch!==requestEpoch||selected?.id!==planId)return;$('history-panel').hidden=false;$('history-title').textContent=label+' · '+(target==='*'?'whole case':target);$('history').replaceChildren();
