$('upload').onsubmit=event=>{event.preventDefault();run(async()=>{
  if(busy)return;const file=$('return-file').files[0];if(!file)throw new Error('Choose the original review JSON file.');if(file.size>120*1024*1024)throw new Error('This file exceeds the browser upload size. Use the native receiver.');
  remember();const mode=$('receive-mode').value,label=$('return-label').value;
  busy=true;$('upload-button').disabled=true;lock();
  try{
    const bytes=await file.arrayBuffer(),fileSha256=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');
    const packet=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes)),pendingKey='sf-return-upload:'+fileSha256+':'+mode+':'+label;
    let pending=readLocal(pendingKey);if(!pending){pending={operationId:operation(),fileSha256,mode,label};saveLocal(pendingKey,pending);}
    const result=await api('/review-returns/'+mode,'POST',{packet,operationId:pending.operationId,label});sessionStorage.removeItem(pendingKey);
    if(mode==='stage')await choose(result.id,{intake:true});else{
      selected=null;draft={resolutions:{},actor:'',pending:null};historySelection=null;epoch++;
      $('selection').hidden=true;$('empty').hidden=true;$('history-panel').hidden=true;sessionStorage.removeItem('sf-return-selected');
      comparisonFilter=result.id;planPage=0;showComparison(result.id,'RECEIVED');await plans();
    }
    message(mode==='stage'?'The complete returned journal is retained. Review the saved plan before applying.':'The full comparison and reviewer lineage were received into this library.');
  }finally{busy=false;$('upload-button').disabled=false;lock();}
});};
$('apply').onsubmit=event=>{event.preventDefault();run(async()=>{
  if(busy||!selected)return;const id=selected.id,requestEpoch=epoch,key=draftKey(id);
  if(!draft.pending){const resolutions=Object.values(draft.resolutions).filter(r=>r.choice).map(r=>({target:r.target,choice:r.choice,reason:r.reason,...(r.choice==='CUSTOM'?{status:r.status,note:r.note}:{})}));
